const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// Security middleware
// Helmet helps secure Express apps by setting various HTTP headers
app.use(helmet());

// CORS configuration - restrict to specific origins in production
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || '*', // Configure this in production!
  optionsSuccessStatus: 200
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Request logging
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// Parse JSON bodies
app.use(express.json());

// Health check endpoint
app.get('/health', (req, res) => {
  // Basic input validation even for simple endpoints
  const verbose = req.query.verbose === 'true';

  const response = { 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  };

  if (verbose) {
    response.service = 'user-service';
    response.version = '1.0.0';
    // Avoid exposing sensitive system info in production
    if (process.env.NODE_ENV !== 'production') {
      response.hostname = require('os').hostname();
    }
  }

  res.json(response);
});

// Users endpoint
app.get('/users', (req, res) => {
  // In a real app, you'd validate authentication here
  // For now, just sanitize the response
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Never expose sensitive user data like passwords, auth tokens, etc.
  // Consider implementing pagination for large datasets
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;

  // Simple pagination
  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;

  const results = {};

  if (endIndex < users.length) {
    results.next = {
      page: page + 1,
      limit: limit
    };
  }

  if (startIndex > 0) {
    results.previous = {
      page: page - 1,
      limit: limit
    };
  }

  results.results = users.slice(startIndex, endIndex);
  results.total = users.length;

  res.json(results);
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Internal Server Error:', error);

  // Don't expose stack traces or detailed error info in production
  res.status(500).json({
    error: 'Internal server error'
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  // Log with appropriate log level
  console.log(`Server running on port ${PORT}${process.env.NODE_ENV === 'production' ? ' in production mode' : ''}`);
});

module.exports = app;

const dotenv = require('dotenv');
const path = require('path');

// Load environment variables based on NODE_ENV
const envFile = process.env.NODE_ENV 
  ? `.env.${process.env.NODE_ENV}` 
  : '.env';

// Load environment variables from file
const envPath = path.join(__dirname, envFile);
dotenv.config({ path: envPath });

// Function to get environment variable with validation
function getEnvVar(name, defaultValue = null) {
  const value = process.env[name];

  if (value === undefined || value === null) {
    if (defaultValue !== null) {
      return defaultValue;
    }

    // Don't start the application without required secrets
    throw new Error(`Missing required environment variable: ${name}`);
  }

  return value;
}

// Securely access your secrets
const config = {
  // Database configuration
  databaseUrl: getEnvVar('DATABASE_URL'),

  // AWS configuration
  aws: {
    accessKeyId: getEnvVar('AWS_ACCESS_KEY_ID'),
    secretAccessKey: getEnvVar('AWS_SECRET_ACCESS_KEY'),
    region: getEnvVar('AWS_REGION', 'us-east-1')
  },

  // API keys
  anthropicApiKey: getEnvVar('ANTHROPIC_API_KEY'),
  stripeSecretKey: getEnvVar('STRIPE_SECRET_KEY'),
  logfireToken: getEnvVar('LOGFIRE_TOKEN')
};

// Never log secrets
function sanitizeConfig(configObj) {
  const sanitized = { ...configObj };
  if (sanitized.aws) {
    sanitized.aws.accessKeyId = '[REDACTED]';
    sanitized.aws.secretAccessKey = '[REDACTED]';
  }
  if (sanitized.anthropicApiKey) sanitized.anthropicApiKey = '[REDACTED]';
  if (sanitized.stripeSecretKey) sanitized.stripeSecretKey = '[REDACTED]';
  if (sanitized.logfireToken) sanitized.logfireToken = '[REDACTED]';

  return sanitized;
}

console.log('Application configuration loaded:', sanitizeConfig(config));

module.exports = config;

